function icon(name, label, keywords, path) {
  return { name, label, keywords, path };
}

export function findPhosphorIcon(name) {
  return PHOSPHOR_ICONS.find((iconItem) => iconItem.name === name) ?? PHOSPHOR_ICONS[0];
}

export function searchPhosphorIcons(query) {
  const normalized = String(query ?? '').normalize('NFKC').trim().toLowerCase();
  if (!normalized) return PHOSPHOR_ICONS;
  return PHOSPHOR_ICONS.filter((iconItem) =>
    iconItem.name.includes(normalized)
    || iconItem.label.toLowerCase().includes(normalized)
    || iconItem.keywords.some((keyword) => keyword.includes(normalized))
  );
}

export function renderPhosphorIcon(name, { className = '', title = '' } = {}) {
  const iconItem = findPhosphorIcon(name);
  const titleMarkup = title ? `<title>${escapeHtml(title)}</title>` : '';
  const aria = title ? ` role="img" aria-label="${escapeHtml(title)}"` : ' aria-hidden="true"';
  return `<svg class="phosphor-icon ${escapeHtml(className)}" viewBox="0 0 256 256" fill="currentColor"${aria}>${titleMarkup}<path d="${iconItem.path}"/></svg>`;
}

function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}
